FUNCTION_BLOCK FB_GlassLehr_AirBladeQuenchPolarimeter
(*
========================================================================================================================
  PROJECT      : ULTRA-PRECISION ARCHITECTURAL FLOAT GLASS CONTINUOUS ANNEALING LEHR (RIBBON WIDTH: 4200 mm)
  SUBSYSTEM    : CROSS-BELT THERMAL CURVATURE POLARIMETRY & MULTI-ZONE TRANSVERSE AIR BLADE QUENCH
  DESIGNATION  : SIL-2 / CLASS 1 DIV 2 CONTINUOUS LEHR CYBER-PHYSICAL AUTOMATION CONTROLLER
  SPECIFICATION: IEC 61131-3 3RD EDITION / ISA-18.2 ALARM MANAGEMENT / ISA-88 CONTINUOUS STATE MACHINE
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  CYBER-PHYSICAL AND THERMOMECHANICAL FORMULATION:
    1. VISCOELASTIC RELAXATION AND RESIDUAL STRESS FIELD IN SODA-LIME SILICATE GLASS:
       Float glass ribbon enters the lehr annealing zone between the glass transition dilatometric softening range:
           Annealing Point (viscosity eta = 10^13.0 dPa*s, ~550 deg C)
           Strain Point    (viscosity eta = 10^14.5 dPa*s, ~505 deg C)
       In this critical cooling interval (Zone B), stress relaxation follows the Tool-Narayanaswamy-Moynihan (TNM)
       fictive temperature phenomenological framework:
           T_f(t) = T(t) - Integral_0^t [ M(xi(t) - xi(t')) * (dT/dt') ] dt'
       where M(xi) = exp(-(xi / tau0)^beta) is the Kohlrausch-Williams-Watts (KWW) stretched exponential relaxation function.
       If cross-belt temperature gradients dT(y)/dy or through-thickness gradients d2T(z)/dz2 develop during transit
       through the annealing range, differential viscoelastic contraction freezes into permanent residual macroscopic
       birefringence and cross-curvature warpage:
           sigma_res(y) = E / (1 - nu) * [ alpha_liquid * (T(y) - T_f(y)) + alpha_glass * Delta T_transverse(y) ]

    2. PHOTOELASTIC POLARIMETRY BIREFRINGENCE MAPPING:
       Residual mechanical principal stresses (sigma_1 - sigma_2) create optical anisotropy characterized by Brewster's
       stress-optic law:
           Delta = C_Brewster * d_glass * (sigma_1 - sigma_2)
       where:
           Delta      = Optical path difference (retardation) [nm]
           d_glass    = Glass ribbon thickness [cm]
           C_Brewster = Stress-optic coefficient (~2.65 x 10^-12 Pa^-1 for float soda-lime glass)
           sigma_res  = Optical retardation per unit thickness [nm/cm]
       Acceptable residual stress for automated downstream scoring and clean diamond cutting requires:
           sigma_res <= 25.0 nm/cm (annealed plate standard)
           sigma_res > 50.0 nm/cm induces catastrophic spontaneous ribbon fracturing during edge trimming.

    3. MULTI-ZONE TRANSVERSE IMPINGEMENT AIR BLADE QUENCH DYNAMICS:
       Quench Zone D/F employs aerodynamically shaped slot air blades providing high-velocity impingement jets.
       The local convective Nusselt number Nu_slot is parameterized via Martin's correlation:
           Nu = 2 / f_geom * Re^0.67 * Pr^0.42 * (1 + (H / (2 * W))^-0.5)
       where Re = (rho * v_jet * 2W) / mu. Center and edge slot damper actuators modulate local stagnation pressure
       [mbar] to sculpt an inverted parabolic thermal extraction profile, countering natural ribbon edge radiation loss.

    4. MULTI-VARIABLE STATE-SPACE MODEL & MODEL PREDICTIVE CONTROL (MPC):
       The linearized discrete state-space formulation at sample time T_s = 200 ms:
           x[k+1] = A * x[k] + B * u[k] + E * d[k]
           y[k]   = C * x[k]
       State Vector x = [
           x1: Transverse Edge-to-Center thermal difference [deg C]
           x2: Top-to-Bottom thermal asymmetry gradient [deg C]
           x3: Voted cross-belt optical retardation stress deviation [nm/cm]
           x4: Ribbon crown/bow physical curvature deflection [mm]
       ]^T
       Control Input Vector u = [
           u1: Center air blade damper modulation [%]
           u2: Edge air blade damper modulation [%]
           u3: Radiant electrical zone heating trim [%]
           u4: Lower quench balancing ratio trim [%]
       ]^T
       Disturbance Vector d = [
           d1: Lehr ribbon line speed variation [m/min]
           d2: Glass ribbon thickness fluctuation [mm]
       ]^T

    5. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) POLARIMETRY VOTING CORE:
       Three spatially parallel optical polarimeter transmission channels monitor cross-belt retardation.
       An automated 2oo3 voter performs peer-consistency delta screening (tolerance = 4.5 nm/cm), isolating
       fouled prisms, laser diode degradation, or optical window obscuration, smoothly degrading to 2oo2, 1oo1,
       or physical feedforward thermal fallback without process disturbance.
========================================================================================================================
*)

VAR_INPUT
    (* --- Supervisory Permissives & Safety Interlocks --- *)
    bMasterEnable               : BOOL;     (* Master lehr automation permissive [TRUE = System Operational] *)
    bSafetyEStopOk              : BOOL;     (* Hardwired SIL-3 emergency line stop safety loop [TRUE = Healthy] *)
    bAutoModeSelect             : BOOL;     (* Supervisory control mode: TRUE = Full Closed-Loop MPC, FALSE = Safe Coordinated *)

    (* --- Float Glass Kinematics & Dimensional Instrumentation --- *)
    rRibbonSpeed_mpm            : REAL;     (* Continuous float ribbon conveyor line speed [m/min] (1.0 .. 35.0) *)
    rRibbonThickness_mm         : REAL;     (* Laser-triangulated glass ribbon thickness [mm] (1.5 .. 25.0) *)
    rThermalCurvature_mm        : REAL;     (* Laser profilometer cross-belt crown/bow warpage [mm] (-15.0 .. +15.0) *)
    bRibbonBreakDetect          : BOOL;     (* Optical reflection ribbon continuity loss flag [TRUE = Ribbon Fractured] *)

    (* --- Transverse Thermal Profile Pyrometry --- *)
    rGlassTemp_LeftEdge_DegC    : REAL;     (* Left edge narrow-band optical pyrometer [deg C] (50.0 .. 650.0) *)
    rGlassTemp_Center_DegC      : REAL;     (* Center ribbon narrow-band optical pyrometer [deg C] (50.0 .. 650.0) *)
    rGlassTemp_RightEdge_DegC   : REAL;     (* Right edge narrow-band optical pyrometer [deg C] (50.0 .. 650.0) *)
    rGlassTemp_Bottom_DegC      : REAL;     (* Bottom surface central infrared radiation pyrometer [deg C] (50.0 .. 650.0) *)

    (* --- 2oo3 Triple Modular Redundant (TMR) Polarimeter Channels --- *)
    rPolarimeterRetard_Ch1_nmcm : REAL;     (* TMR Polarimeter Channel 1 optical retardation [nm/cm] (0.0 .. 150.0) *)
    rPolarimeterRetard_Ch2_nmcm : REAL;     (* TMR Polarimeter Channel 2 optical retardation [nm/cm] (0.0 .. 150.0) *)
    rPolarimeterRetard_Ch3_nmcm : REAL;     (* TMR Polarimeter Channel 3 optical retardation [nm/cm] (0.0 .. 150.0) *)

    (* --- Aerodynamic Air Blade Quench Instrumentation --- *)
    rAirBladePlenumPress_mbar   : REAL;     (* Upper quench air blade main plenum supply pressure [mbar] (0.0 .. 120.0) *)
    rLowerBladePlenumPress_mbar : REAL;     (* Lower quench air blade main plenum supply pressure [mbar] (0.0 .. 120.0) *)
    rQuenchInletAirTemp_DegC    : REAL;     (* Ambient supply air temperature into quench blowers [deg C] (10.0 .. 60.0) *)
    bBlowerVFD_Fault            : BOOL;     (* Quench variable frequency drive collective fault [TRUE = Faulted] *)
END_VAR

VAR_OUTPUT
    (* --- Automation Readiness & Operating Mode Flags --- *)
    bSystemReady                : BOOL;     (* Lehr cross-belt cooling and polarimetry supervisory ready *)
    bDegradedModeActive         : BOOL;     (* Operating in degraded TMR sensor or actuator fallback mode *)

    (* --- Multi-Zone Air Blade Quench Actuation Commands --- *)
    rCenterAirBladeDamper_Pct   : REAL;     (* Center zone air blade modulating damper command [%] (0.0 .. 100.0) *)
    rEdgeAirBladeDamper_Pct     : REAL;     (* Symmetrical edge air blade trim damper command [%] (0.0 .. 100.0) *)
    rLowerQuenchBalance_Pct     : REAL;     (* Lower quench vs upper quench airflow balancing trim [%] (0.0 .. 100.0) *)
    rBlowerSpeedRef_RPM         : REAL;     (* Quench main turbo-blower VFD speed reference [RPM] (0.0 .. 3000.0) *)

    (* --- Thermal Curvature Radiant Heating Actuation --- *)
    rElectricRadiantHeater_Pct  : REAL;     (* Cross-belt radiant trim electrical heater SCR power [%] (0.0 .. 100.0) *)

    (* --- Validated Process Telemetry & Diagnostics --- *)
    rVotedResidualStress_nmcm   : REAL;     (* 2oo3 TMR resolved cross-belt optical retardation stress [nm/cm] *)
    rCrossBeltTempGradient_DegC : REAL;     (* Validated edge-to-center transverse thermal gradient [deg C] *)
    rThroughThicknessGrad_DegC  : REAL;     (* Top-to-bottom through-thickness thermal differential [deg C] *)
    wAlarmWord                  : WORD;     (* ISA-18.2 packed alarm annunciator word *)
    wSystemStatusWord           : WORD;     (* Active operational state and diagnostics status word *)
END_VAR

VAR
    (* --- State Machine Sequencing Registers --- *)
    iState                      : INT := 0; (* Operational state index *)
    iPreviousState              : INT := 0; (* Previous execution state *)

    (* --- 2oo3 TMR Voting & Fault Isolation Registers --- *)
    bCh1_Valid                  : BOOL := TRUE;
    bCh2_Valid                  : BOOL := TRUE;
    bCh3_Valid                  : BOOL := TRUE;
    iHealthySensorCount         : INT  := 3;
    rTmrDelta12                 : REAL := 0.0;
    rTmrDelta23                 : REAL := 0.0;
    rTmrDelta31                 : REAL := 0.0;
    rTmrToleranceLimit          : REAL := 4.5;  (* Maximum allowable inter-channel divergence [nm/cm] *)

    (* --- State-Space Discrete Dynamics Model Variables (Sampling dt = 0.20 s) --- *)
    (* State Vector:
         x1 = Delta T_transverse (Average Edge Temp - Center Temp) [deg C]
         x2 = Delta T_vertical (Center Top Temp - Bottom Temp) [deg C]
         x3 = Residual stress retardation deviation from setpoint (Target = 15.0 nm/cm)
         x4 = Ribbon bow/curvature warpage deviation from planarity [mm]
    *)
    rState_x1_TransverseGrad    : REAL := 0.0;
    rState_x2_ThroughThickGrad  : REAL := 0.0;
    rState_x3_StressError       : REAL := 0.0;
    rState_x4_CurvatureDeflect  : REAL := 0.0;

    (* Model Predictive Matrices: System Plant Matrix A (Discretized at 200 ms) *)
    rA11 : REAL := 0.9650;  rA12 : REAL := 0.0120;  rA13 : REAL := 0.0000;  rA14 : REAL := 0.0040;
    rA21 : REAL := 0.0080;  rA22 : REAL := 0.9410;  rA23 : REAL := 0.0000;  rA24 : REAL := -0.0150;
    rA31 : REAL := 0.2850;  rA32 : REAL := 0.1420;  rA33 : REAL := 0.8800;  rA34 : REAL := 0.0950;
    rA41 : REAL := 0.0210;  rA42 : REAL := -0.0450; rA43 : REAL := 0.0065;  rA44 : REAL := 0.9720;

    (* Control Authority Matrix B *)
    rB11 : REAL := -0.0820; (* Center damper effect on transverse gradient *)
    rB12 : REAL := 0.0940;  (* Edge damper effect on transverse gradient *)
    rB13 : REAL := -0.0550; (* Radiant heater effect on transverse gradient *)
    rB24 : REAL := -0.0760; (* Lower quench balancing effect on vertical gradient *)
    rB31 : REAL := -0.0420; (* Center damper effect on stress retardation *)
    rB33 : REAL := -0.0650; (* Radiant heater annealing stress relaxation *)
    rB41 : REAL := 0.0180;  (* Center damper on physical curvature *)
    rB44 : REAL := 0.0340;  (* Lower quench on physical curvature *)

    (* Disturbance Coupling Matrix E *)
    rE11 : REAL := 0.0240;  (* Line speed influence on transverse cooling *)
    rE12 : REAL := -0.1150; (* Ribbon thickness influence on thermal gradient *)
    rE31 : REAL := 0.0550;  (* Line speed influence on residual stress *)
    rE32 : REAL := 0.2100;  (* Ribbon thickness influence on residual stress *)

    (* Predictive Receding Horizon Deviation Estimates *)
    rPredTransverseGrad_k1      : REAL := 0.0;
    rPredThroughThickGrad_k1    : REAL := 0.0;
    rPredStressError_k1         : REAL := 0.0;
    rPredCurvatureDeflect_k1    : REAL := 0.0;

    (* Setpoint Targets and Tuning Parameters *)
    rTargetResidualStress_nmcm  : REAL := 15.0; (* Optimal target residual birefringence [nm/cm] *)
    rTargetCurvature_mm         : REAL := 0.0;  (* Perfect planarity target [mm] *)
    rMaxAllowableStress_nmcm    : REAL := 38.0; (* Quality cut-off limit [nm/cm] *)
    rCriticalTripStress_nmcm    : REAL := 55.0; (* Immediate ribbon rupture hazard [nm/cm] *)

    (* Low-Pass Signal Conditioners *)
    rFiltRibbonSpeed_mpm        : REAL := 12.0;
    rFiltRibbonThickness_mm     : REAL := 4.0;
    rFiltLeftTemp_DegC          : REAL := 540.0;
    rFiltCenterTemp_DegC        : REAL := 550.0;
    rFiltRightTemp_DegC         : REAL := 540.0;
    rFiltBottomTemp_DegC        : REAL := 548.0;
    rFiltCurvature_mm           : REAL := 0.0;
    rFiltPlenumPress_mbar       : REAL := 35.0;

    (* Hardware Timers and Event Watchdogs *)
    tonLehrStartupPurge         : TON;
    tonThermalStabilityTimer    : TON;
    tonPolarimeterFaultDebounce : TON;
    tonStressSurgeWatchdog      : TON;
    tonBlowerRampDelay          : TON;

    (* Cycle Execution & Production Telemetry *)
    udiExecutionCycles          : UDINT := 0;
    udiStressSurgeCount         : UDINT := 0;
    rIntegratedStressIntegral   : REAL  := 0.0;
END_VAR

(*
========================================================================================================================
  CYCLIC DETERMINISTIC EXECUTION ALGORITHM
========================================================================================================================
*)

udiExecutionCycles := udiExecutionCycles + 1;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: HARDWIRED SAFETY INTERLOCKS & IMMEDIATE FIRST-OUT FAULT TRIPPING
   --------------------------------------------------------------------------------------------------------------------- *)
IF (NOT bSafetyEStopOk) OR bRibbonBreakDetect OR bBlowerVFD_Fault THEN
    (* Immediate Deterministic De-energization and Safe-State Positioning *)
    bSystemReady                := FALSE;
    bDegradedModeActive         := FALSE;
    rCenterAirBladeDamper_Pct   := 0.0;
    rEdgeAirBladeDamper_Pct     := 0.0;
    rElectricRadiantHeater_Pct  := 0.0;     (* Immediate SCR shutoff to avoid thermal fracture *)
    rLowerQuenchBalance_Pct     := 50.0;    (* Neutral airflow balance *)
    rBlowerSpeedRef_RPM         := 600.0;   (* Drop to emergency idle scavenge speed *)

    (* Set Diagnostic Alarm Bits *)
    wAlarmWord.0 := NOT bSafetyEStopOk;     (* E-Stop Trip Active *)
    wAlarmWord.1 := bRibbonBreakDetect;     (* Ribbon Fracture Interlock *)
    wAlarmWord.2 := bBlowerVFD_Fault;       (* Quench Blower Drive Fault *)

    wSystemStatusWord := 16#F000;           (* Status: Emergency Tripped Safe-State *)
    iState := 99;                           (* Force State Machine into Safe Shutdown *)
    RETURN;
END_IF;

wAlarmWord.0 := FALSE;
wAlarmWord.1 := FALSE;
wAlarmWord.2 := FALSE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) POLARIMETRY RETARDATION VOTING CORE
   --------------------------------------------------------------------------------------------------------------------- *)
(* Step 2.1: Individual Channel Validity Range Boundary Check (0.0 to 140.0 nm/cm) *)
bCh1_Valid := (rPolarimeterRetard_Ch1_nmcm >= 0.0) AND (rPolarimeterRetard_Ch1_nmcm <= 140.0);
bCh2_Valid := (rPolarimeterRetard_Ch2_nmcm >= 0.0) AND (rPolarimeterRetard_Ch2_nmcm <= 140.0);
bCh3_Valid := (rPolarimeterRetard_Ch3_nmcm >= 0.0) AND (rPolarimeterRetard_Ch3_nmcm <= 140.0);

(* Step 2.2: Compute Inter-Channel Peer Residual Retardation Discrepancies *)
rTmrDelta12 := ABS(rPolarimeterRetard_Ch1_nmcm - rPolarimeterRetard_Ch2_nmcm);
rTmrDelta23 := ABS(rPolarimeterRetard_Ch2_nmcm - rPolarimeterRetard_Ch3_nmcm);
rTmrDelta31 := ABS(rPolarimeterRetard_Ch3_nmcm - rPolarimeterRetard_Ch1_nmcm);

(* Step 2.3: Consensus Resolution and Optical Channel Isolation Logic *)
IF bCh1_Valid AND bCh2_Valid AND bCh3_Valid THEN
    IF (rTmrDelta12 <= rTmrToleranceLimit) AND (rTmrDelta23 <= rTmrToleranceLimit) AND (rTmrDelta31 <= rTmrToleranceLimit) THEN
        (* All three polarimeter channels in full geometric consensus - True 2oo3 mean *)
        rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch1_nmcm + rPolarimeterRetard_Ch2_nmcm + rPolarimeterRetard_Ch3_nmcm) / 3.0;
        iHealthySensorCount       := 3;
        wAlarmWord.3              := FALSE; (* TMR Divergence Clear *)
        wAlarmWord.4              := FALSE;
    ELSIF (rTmrDelta12 <= rTmrToleranceLimit) AND (rTmrDelta23 > rTmrToleranceLimit) AND (rTmrDelta31 > rTmrToleranceLimit) THEN
        (* Channel 3 drifted or fouled: Discard Ch3, vote 1 and 2 *)
        rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch1_nmcm + rPolarimeterRetard_Ch2_nmcm) / 2.0;
        bCh3_Valid                := FALSE;
        iHealthySensorCount       := 2;
        wAlarmWord.3              := TRUE;  (* Channel 3 divergence warning *)
    ELSIF (rTmrDelta23 <= rTmrToleranceLimit) AND (rTmrDelta12 > rTmrToleranceLimit) AND (rTmrDelta31 > rTmrToleranceLimit) THEN
        (* Channel 1 drifted or fouled: Discard Ch1, vote 2 and 3 *)
        rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch2_nmcm + rPolarimeterRetard_Ch3_nmcm) / 2.0;
        bCh1_Valid                := FALSE;
        iHealthySensorCount       := 2;
        wAlarmWord.3              := TRUE;  (* Channel 1 divergence warning *)
    ELSIF (rTmrDelta31 <= rTmrToleranceLimit) AND (rTmrDelta12 > rTmrToleranceLimit) AND (rTmrDelta23 > rTmrToleranceLimit) THEN
        (* Channel 2 drifted or fouled: Discard Ch2, vote 1 and 3 *)
        rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch1_nmcm + rPolarimeterRetard_Ch3_nmcm) / 2.0;
        bCh2_Valid                := FALSE;
        iHealthySensorCount       := 2;
        wAlarmWord.3              := TRUE;  (* Channel 2 divergence warning *)
    ELSE
        (* Total TMR Incoherence: Multiple optical paths degraded simultaneously *)
        rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch1_nmcm + rPolarimeterRetard_Ch2_nmcm + rPolarimeterRetard_Ch3_nmcm) / 3.0;
        iHealthySensorCount       := 1;
        wAlarmWord.3              := TRUE;
        wAlarmWord.4              := TRUE;  (* Severe Polarimeter Incoherence Alarm *)
    END_IF;
ELSIF bCh1_Valid AND bCh2_Valid THEN
    rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch1_nmcm + rPolarimeterRetard_Ch2_nmcm) / 2.0;
    iHealthySensorCount       := 2;
    wAlarmWord.3              := TRUE;
ELSIF bCh2_Valid AND bCh3_Valid THEN
    rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch2_nmcm + rPolarimeterRetard_Ch3_nmcm) / 2.0;
    iHealthySensorCount       := 2;
    wAlarmWord.3              := TRUE;
ELSIF bCh1_Valid AND bCh3_Valid THEN
    rVotedResidualStress_nmcm := (rPolarimeterRetard_Ch1_nmcm + rPolarimeterRetard_Ch3_nmcm) / 2.0;
    iHealthySensorCount       := 2;
    wAlarmWord.3              := TRUE;
ELSIF bCh1_Valid THEN
    rVotedResidualStress_nmcm := rPolarimeterRetard_Ch1_nmcm;
    iHealthySensorCount       := 1;
    wAlarmWord.4              := TRUE;
ELSIF bCh2_Valid THEN
    rVotedResidualStress_nmcm := rPolarimeterRetard_Ch2_nmcm;
    iHealthySensorCount       := 1;
    wAlarmWord.4              := TRUE;
ELSIF bCh3_Valid THEN
    rVotedResidualStress_nmcm := rPolarimeterRetard_Ch3_nmcm;
    iHealthySensorCount       := 1;
    wAlarmWord.4              := TRUE;
ELSE
    (* Total Sensor Loss: Synthesize residual stress from transverse temperature gradient *)
    rVotedResidualStress_nmcm := ABS(rFiltLeftTemp_DegC - rFiltCenterTemp_DegC) * 1.65;
    iHealthySensorCount       := 0;
    wAlarmWord.4              := TRUE;  (* Critical: Polarimetry Synthetic Estimation Active *)
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: PROCESS VARIABLE CONDITIONING & STATE-SPACE RECURSIVE ESTIMATION
   --------------------------------------------------------------------------------------------------------------------- *)
(* First-order digital exponential smoothing filters (Sampling interval Ts = 200 ms) *)
rFiltRibbonSpeed_mpm    := (rFiltRibbonSpeed_mpm * 0.85) + (rRibbonSpeed_mpm * 0.15);
rFiltRibbonThickness_mm := (rFiltRibbonThickness_mm * 0.90) + (rRibbonThickness_mm * 0.10);
rFiltLeftTemp_DegC      := (rFiltLeftTemp_DegC * 0.80) + (rGlassTemp_LeftEdge_DegC * 0.20);
rFiltCenterTemp_DegC    := (rFiltCenterTemp_DegC * 0.80) + (rGlassTemp_Center_DegC * 0.20);
rFiltRightTemp_DegC     := (rFiltRightTemp_DegC * 0.80) + (rGlassTemp_RightEdge_DegC * 0.20);
rFiltBottomTemp_DegC    := (rFiltBottomTemp_DegC * 0.80) + (rGlassTemp_Bottom_DegC * 0.20);
rFiltCurvature_mm       := (rFiltCurvature_mm * 0.75) + (rThermalCurvature_mm * 0.25);
rFiltPlenumPress_mbar   := (rFiltPlenumPress_mbar * 0.85) + (rAirBladePlenumPress_mbar * 0.15);

(* Thermodynamic Gradient Synthesis *)
rCrossBeltTempGradient_DegC := ((rFiltLeftTemp_DegC + rFiltRightTemp_DegC) / 2.0) - rFiltCenterTemp_DegC;
rThroughThicknessGrad_DegC  := rFiltCenterTemp_DegC - rFiltBottomTemp_DegC;

(* Update State Deviation Vector x *)
rState_x1_TransverseGrad   := rCrossBeltTempGradient_DegC;
rState_x2_ThroughThickGrad := rThroughThicknessGrad_DegC;
rState_x3_StressError      := rVotedResidualStress_nmcm - rTargetResidualStress_nmcm;
rState_x4_CurvatureDeflect := rFiltCurvature_mm - rTargetCurvature_mm;

(* Cumulative Stress History Integration (Quality Metric) *)
rIntegratedStressIntegral := rIntegratedStressIntegral + (rVotedResidualStress_nmcm * 0.20);

(* One-Step Ahead Model Predictive Receding Horizon Prediction: x[k+1] = A * x[k] + E * d[k] *)
rPredTransverseGrad_k1 := (rA11 * rState_x1_TransverseGrad) + (rA12 * rState_x2_ThroughThickGrad)
                        + (rA14 * rState_x4_CurvatureDeflect)
                        + (rE11 * (rFiltRibbonSpeed_mpm - 12.0)) + (rE12 * (rFiltRibbonThickness_mm - 4.0));

rPredThroughThickGrad_k1 := (rA21 * rState_x1_TransverseGrad) + (rA22 * rState_x2_ThroughThickGrad)
                          + (rA24 * rState_x4_CurvatureDeflect);

rPredStressError_k1 := (rA31 * rState_x1_TransverseGrad) + (rA32 * rState_x2_ThroughThickGrad)
                     + (rA33 * rState_x3_StressError) + (rA34 * rState_x4_CurvatureDeflect)
                     + (rE31 * (rFiltRibbonSpeed_mpm - 12.0)) + (rE32 * (rFiltRibbonThickness_mm - 4.0));

rPredCurvatureDeflect_k1 := (rA41 * rState_x1_TransverseGrad) + (rA42 * rState_x2_ThroughThickGrad)
                          + (rA43 * rState_x3_StressError) + (rA44 * rState_x4_CurvatureDeflect);

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: FINITE STATE MACHINE (ISA-88 MODULAR EXECUTION STATES)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_LEHR_COLD_INIT: Baseline Calibration & Optical Zero Tare *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := FALSE;
        rCenterAirBladeDamper_Pct   := 15.0; (* Minimum purge clearance *)
        rEdgeAirBladeDamper_Pct     := 15.0;
        rElectricRadiantHeater_Pct  := 0.0;
        rLowerQuenchBalance_Pct     := 50.0;
        rBlowerSpeedRef_RPM         := 800.0; (* Scavenge blower circulation *)
        wSystemStatusWord           := 16#0001;

        tonLehrStartupPurge(IN := bMasterEnable, PT := T#10S);
        IF tonLehrStartupPurge.Q THEN
            tonLehrStartupPurge(IN := FALSE);
            IF (rAirBladePlenumPress_mbar >= 15.0) AND (iHealthySensorCount >= 2) THEN
                iState := 10; (* Proceed to Pre-Anneal Line Sync *)
            ELSE
                wAlarmWord.5 := TRUE; (* Startup Plenum Pressure or Polarimeter Inadequate *)
            END_IF;
        END_IF;

    10: (* STATE_PRE_ANNEAL_LINE_SYNC: Lehr Conveyor & Thermal Soaking Synchronization *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := FALSE;
        rCenterAirBladeDamper_Pct   := 30.0;
        rEdgeAirBladeDamper_Pct     := 20.0;
        rElectricRadiantHeater_Pct  := 25.0; (* Pre-heating radiant roof bank *)
        rLowerQuenchBalance_Pct     := 50.0;
        rBlowerSpeedRef_RPM         := 1200.0 + (rFiltRibbonSpeed_mpm * 45.0);
        wSystemStatusWord           := 16#0010;

        tonThermalStabilityTimer(IN := (rFiltCenterTemp_DegC >= 480.0), PT := T#15S);
        IF tonThermalStabilityTimer.Q THEN
            tonThermalStabilityTimer(IN := FALSE);
            IF bAutoModeSelect THEN
                iState := 20; (* Transition into Closed-Loop MPC Regulation *)
            END_IF;
        END_IF;

        IF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    20: (* STATE_NORMAL_MPC_REGULATION: Active Optimal Cross-Belt Air Blade & Polarimeter Control *)
        bSystemReady        := TRUE;
        bDegradedModeActive := (iHealthySensorCount < 3);
        wSystemStatusWord   := 16#0020;

        (* Sub-Loop A: Transverse Air Blade Damper Differential Modulation *)
        (* Center damper extracts heat from ribbon core; edge damper compensates for edge radiation loss *)
        rCenterAirBladeDamper_Pct := 45.0 + (rPredTransverseGrad_k1 * -1.85) + (rPredStressError_k1 * 0.75);
        rEdgeAirBladeDamper_Pct   := 35.0 + (rPredTransverseGrad_k1 * 1.60)  - (rPredCurvatureDeflect_k1 * 1.20);

        (* Sub-Loop B: Radiant Electrical Trim Heating Array *)
        (* When edges cool too fast (negative gradient), radiant edge trim delivers thermal compensation *)
        IF rPredTransverseGrad_k1 < -4.0 THEN
            rElectricRadiantHeater_Pct := ABS(rPredTransverseGrad_k1) * 4.80 + (rPredStressError_k1 * 0.45);
        ELSE
            rElectricRadiantHeater_Pct := 10.0; (* Base simmering roof power *)
        END_IF;

        (* Sub-Loop C: Lower Quench Airflow Balancing Trim *)
        (* Balances top-to-bottom cooling to suppress longitudinal and cross-belt bow/curl *)
        rLowerQuenchBalance_Pct := 50.0 + (rPredThroughThickGrad_k1 * 2.20) + (rPredCurvatureDeflect_k1 * 3.10);

        (* Sub-Loop D: Quench Turbo-Blower Main VFD Modulation based on mass throughput *)
        (* Mass throughput is proportional to line speed multiplied by glass thickness *)
        rBlowerSpeedRef_RPM := 950.0 + (rFiltRibbonSpeed_mpm * rFiltRibbonThickness_mm * 28.5)
                             + (rFiltCenterTemp_DegC * 0.75);

        (* Actuation Mechanical Saturation Limits *)
        IF rCenterAirBladeDamper_Pct > 95.0 THEN rCenterAirBladeDamper_Pct := 95.0; END_IF;
        IF rCenterAirBladeDamper_Pct < 5.0  THEN rCenterAirBladeDamper_Pct := 5.0;  END_IF;
        IF rEdgeAirBladeDamper_Pct > 95.0   THEN rEdgeAirBladeDamper_Pct := 95.0;   END_IF;
        IF rEdgeAirBladeDamper_Pct < 5.0    THEN rEdgeAirBladeDamper_Pct := 5.0;    END_IF;
        IF rElectricRadiantHeater_Pct > 100.0 THEN rElectricRadiantHeater_Pct := 100.0; END_IF;
        IF rElectricRadiantHeater_Pct < 0.0   THEN rElectricRadiantHeater_Pct := 0.0;   END_IF;
        IF rLowerQuenchBalance_Pct > 80.0   THEN rLowerQuenchBalance_Pct := 80.0;   END_IF;
        IF rLowerQuenchBalance_Pct < 20.0   THEN rLowerQuenchBalance_Pct := 20.0;   END_IF;
        IF rBlowerSpeedRef_RPM > 2950.0     THEN rBlowerSpeedRef_RPM := 2950.0;     END_IF;
        IF rBlowerSpeedRef_RPM < 600.0      THEN rBlowerSpeedRef_RPM := 600.0;      END_IF;

        (* Dynamic Process State Transitions *)
        IF ABS(rFiltCurvature_mm) > 4.5 THEN
            iState := 30; (* Excessive Ribbon Crown / Bow Curvature *)
        ELSIF rVotedResidualStress_nmcm > rMaxAllowableStress_nmcm THEN
            iState := 40; (* Residual Retardation Birefringence Surge *)
        ELSIF (iHealthySensorCount <= 1) THEN
            iState := 50; (* Degraded Sensor Fallback *)
        END_IF;

    30: (* STATE_THERMAL_CURVATURE_CORRECTION: Intensive Cross-Belt Warp Neutralization *)
        bSystemReady        := TRUE;
        bDegradedModeActive := TRUE;
        wSystemStatusWord   := 16#0030;
        wAlarmWord.6        := TRUE; (* Excessive Thermal Curvature Alarm *)

        (* Aggressive Asymmetric Air Blade and Radiant Thermal Profiling *)
        IF rFiltCurvature_mm > 0.0 THEN
            (* Convex upward bow: Increase top center quench and boost bottom balancing *)
            rCenterAirBladeDamper_Pct  := 75.0;
            rEdgeAirBladeDamper_Pct    := 25.0;
            rLowerQuenchBalance_Pct    := 68.0;
            rElectricRadiantHeater_Pct := 45.0;
        ELSE
            (* Concave downward curl: Suppress top center air blade and increase edge heating *)
            rCenterAirBladeDamper_Pct  := 25.0;
            rEdgeAirBladeDamper_Pct    := 60.0;
            rLowerQuenchBalance_Pct    := 32.0;
            rElectricRadiantHeater_Pct := 75.0;
        END_IF;

        rBlowerSpeedRef_RPM := 1400.0 + (rFiltRibbonSpeed_mpm * 40.0);

        (* Return to Normal State when ribbon curvature re-enters planarity tolerance *)
        IF ABS(rFiltCurvature_mm) <= 1.8 THEN
            wAlarmWord.6 := FALSE;
            iState       := 20;
        END_IF;

    40: (* STATE_RETARDATION_STRESS_SURGE: Stress Relaxation & Annealing Extension *)
        bSystemReady        := TRUE;
        bDegradedModeActive := TRUE;
        wSystemStatusWord   := 16#0040;
        wAlarmWord.7        := TRUE; (* High Residual Optical Birefringence Alarm *)
        udiStressSurgeCount := udiStressSurgeCount + 1;

        (* Slow cooling rate through strain zone to allow viscoelastic relaxation *)
        rElectricRadiantHeater_Pct := 90.0; (* Elevate roof radiant heaters to retard cooling *)
        rCenterAirBladeDamper_Pct  := 18.0; (* Dampen quench air velocity *)
        rEdgeAirBladeDamper_Pct    := 12.0;
        rLowerQuenchBalance_Pct    := 50.0;
        rBlowerSpeedRef_RPM        := 1100.0;

        (* Exit Condition: Retardation safely annealed below quality threshold *)
        IF rVotedResidualStress_nmcm <= 22.0 THEN
            wAlarmWord.7 := FALSE;
            iState       := 20;
        ELSIF rVotedResidualStress_nmcm >= rCriticalTripStress_nmcm THEN
            (* Critical Stress Trip: Spontaneous ribbon fracture imminent *)
            wAlarmWord.8 := TRUE;
            iState       := 99;
        END_IF;

    50: (* STATE_DEGRADED_TMR_FALLBACK: Sensor Failure Feedforward Schedule *)
        bSystemReady        := TRUE;
        bDegradedModeActive := TRUE;
        wSystemStatusWord   := 16#0050;
        wAlarmWord.9        := TRUE; (* Degraded Polarimeter Mode Active *)

        (* Deterministic open-loop schedule parameterized on glass thickness and line speed *)
        rCenterAirBladeDamper_Pct  := 35.0 + (rFiltRibbonThickness_mm * 2.5);
        rEdgeAirBladeDamper_Pct    := 25.0 + (rFiltRibbonThickness_mm * 1.8);
        rElectricRadiantHeater_Pct := 30.0 + (rFiltRibbonSpeed_mpm * 1.2);
        rLowerQuenchBalance_Pct    := 50.0;
        rBlowerSpeedRef_RPM        := 1000.0 + (rFiltRibbonSpeed_mpm * 50.0);

        (* Restore normal state if at least 2 polarimeter channels regain valid consensus *)
        IF (iHealthySensorCount >= 2) AND bAutoModeSelect THEN
            wAlarmWord.9 := FALSE;
            iState       := 20;
        END_IF;

    99: (* STATE_EMERGENCY_LEHR_TRIP: Hard Interlock Shutdown & Roller Preservation *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := FALSE;
        rCenterAirBladeDamper_Pct   := 0.0;
        rEdgeAirBladeDamper_Pct     := 0.0;
        rElectricRadiantHeater_Pct  := 0.0;     (* Immediate zero power *)
        rLowerQuenchBalance_Pct     := 50.0;
        rBlowerSpeedRef_RPM         := 600.0;   (* Gentle air sweep to cool conveyor rollers *)
        wSystemStatusWord           := 16#9999;

        IF bSafetyEStopOk AND (NOT bRibbonBreakDetect) AND (NOT bBlowerVFD_Fault) THEN
            wAlarmWord.8 := FALSE;
            iState       := 0; (* Reset to cold initialization *)
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: ISA-18.2 SECONDARY ALARM HIERARCHY & SAFETY MONITORING
   --------------------------------------------------------------------------------------------------------------------- *)
(* Transverse Thermal Gradient Warning (> 22.0 deg C) *)
IF ABS(rCrossBeltTempGradient_DegC) > 22.0 THEN
    wAlarmWord.10 := TRUE; (* Thermal shock gradient warning *)
ELSE
    wAlarmWord.10 := FALSE;
END_IF;

(* Air Blade Plenum Low Pressure Hazard (< 12.0 mbar during operation) *)
IF (iState >= 20) AND (iState <= 50) AND (rFiltPlenumPress_mbar < 12.0) THEN
    wAlarmWord.11 := TRUE; (* Quench starvation warning *)
ELSE
    wAlarmWord.11 := FALSE;
END_IF;

(* Glass Ribbon Over-Temperature Limit (> 620.0 deg C at lehr entry) *)
IF (rFiltCenterTemp_DegC > 620.0) THEN
    wAlarmWord.12 := TRUE; (* Lehr entrance thermal runaway *)
ELSE
    wAlarmWord.12 := FALSE;
END_IF;

END_FUNCTION_BLOCK
